{
 "id": "watch-gear-geneva",
 "name": "Geneva Step Ring",
 "idea": "A thin raised metal ring with fine tick marks sits on a matte near-black ground with faint diagonal Geneva-stripe sheen; a short brass arc and one ruby dome advance around it in stepped increments (hold, quick eased step, small settle) every two seconds, while the left of the frame stays calm.",
 "use": [
  "loading",
  "progress",
  "hero"
 ],
 "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
void main(){
vec2 R=u_resolution;
vec2 p=(gl_FragCoord.xy-0.5*R)/R.y;
float px=1.5/R.y;
float asp=R.x/R.y;
float k=smoothstep(0.7,1.3,asp);
vec2 c=mix(vec2(0.07,-0.25),vec2(0.5*asp-0.33,0.0),k);
float sc=mix(0.15,0.26,k);
vec2 q=p-c;
float r=length(q);
float side=exp(-r*r/(sc*sc*6.0));
vec3 col=u_c0*(0.86+0.22*side)+u_c2*0.015*side;
float u=(p.x+p.y)*0.7071*30.0+u_time*0.04;
float s=0.5+0.5*cos(fract(u)*6.2831853);
float sweep=0.6+0.4*sin(p.x*2.2-u_time*0.4);
col+=u_c1*0.024*s*side*sweep;
float w=sc*0.045;
float ds=abs(length(q+vec2(0.004,0.013))-sc);
col*=1.0-0.45*exp(-ds*ds/(w*w*4.0));
float T=u_time/2.0;
float n=floor(T);
float f=fract(T);
float e=smoothstep(0.0,0.22,f);
float g=max(f-0.22,0.0);
e+=0.06*sin(g*40.0)*exp(-g*14.0);
float cur=mod((n+e)*0.5235988,6.2831853);
float a=mod(atan(q.x,q.y),6.2831853);
float trail=exp(-mod(cur-a,6.2831853)*1.4);
vec3 L=normalize(vec3(-0.5,0.6,0.65));
vec3 V=vec3(0.0,0.0,1.0);
float d=r-sc;
float h=clamp(d/w,-1.0,1.0);
float m=1.0-smoothstep(w-px,w+px,abs(d));
vec2 dir=q/max(r,0.0001);
vec3 nr=normalize(vec3(dir*h,sqrt(max(1.0-h*h,0.0))+0.05));
float dif=max(dot(nr,L),0.0);
float spec=pow(max(dot(reflect(-L,nr),V),0.0),24.0);
vec3 metal=mix(mix(u_c0,u_c1,0.18),u_c2,0.2+0.8*trail);
vec3 rc=metal*(0.35+0.75*dif)+u_c1*spec*(0.12+0.35*trail);
col=mix(col,rc,m);
float rt=sc-w*2.6;
float fa=a/6.2831853*60.0;
float ti=floor(fa+0.5);
float mj=1.0-step(0.1,mod(ti,5.0));
float tl=w*(0.6+0.7*mj);
float tw=w*(0.16+0.12*mj);
float da=abs(fa-ti)/60.0*6.2831853*r;
float tk=(1.0-smoothstep(tw,tw+px,da))*(1.0-smoothstep(tl,tl+px,abs(r-(rt-tl))));
float tt=exp(-mod(cur-ti/60.0*6.2831853,6.2831853)*1.4);
vec3 tc=mix(mix(u_c0,u_c1,0.24),u_c2*1.1,tt);
col=mix(col,tc,tk*0.85);
vec2 rp=c+sc*vec2(sin(cur),cos(cur));
vec2 rq=p-rp;
float rr=length(rq);
float jr=w*1.5;
col*=1.0-0.4*exp(-dot(rq+vec2(0.003,0.006),rq+vec2(0.003,0.006))/(jr*jr*2.0));
col+=u_c3*0.22*exp(-rr*rr/(jr*jr*7.0));
float jm=1.0-smoothstep(jr-px,jr+px,rr);
float jz=sqrt(max(1.0-rr*rr/(jr*jr),0.0));
vec3 jn=normalize(vec3(rq/jr,jz+0.001));
float jd=max(dot(jn,L),0.0);
float js=pow(max(dot(reflect(-L,jn),V),0.0),40.0);
vec3 jc=u_c3*(0.3+0.85*jd)+mix(u_c3,u_c1,0.7)*js*0.9;
col=mix(col,jc,jm);
col*=1.0-0.15*length(p*vec2(1.0/max(asp,1.0),1.0));
col+=(hash(gl_FragCoord.xy)-0.5)*0.02;
gl_FragColor=vec4(col,1.0);
}",
 "colors": [
  "#121417",
  "#e9e4d8",
  "#c9a24a",
  "#9c2b3b"
 ],
 "reduced": {
  "kind": "fade",
  "at": 9.0,
  "ms": 400,
  "note": "A still raised tick ring on matte black with a short brass arc and one ruby dome resting at a settled step, fading in."
 },
 "cardIds": [
  "watch-movement"
 ],
 "families": [],
 "lensIds": [],
 "styles": [
  "soft-3d-objects",
  "dark-quiet-matte"
 ]
}
```

