{
  "id": "airmail-flap-lift",
  "name": "Airmail Tint Hairline",
  "idea": "A deep navy ground carries a fine engraved line screen in one lower corner whose thick and thin moire bands drift over about 12 seconds and dissolve into halftone dots at their edge, while a single hairline of diagonal red and blue stripes creeps slowly along the bottom edge toward the same corner.",
  "use": [
    "card",
    "empty-state",
    "sheet"
  ],
  "frag": "precision highp float;
uniform vec2 u_resolution;
uniform float u_time;
uniform vec3 u_c0;
uniform vec3 u_c1;
uniform vec3 u_c2;
uniform vec3 u_c3;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(h(i),h(i+vec2(1.0,0.0)),f.x),mix(h(i+vec2(0.0,1.0)),h(i+vec2(1.0,1.0)),f.x),f.y);}
void main(){
vec2 R=u_resolution;
vec2 fc=gl_FragCoord.xy;
vec2 p=(fc-0.5*R)/R.y;
float asp=R.x/R.y;
float t=u_time;
vec2 c=vec2(0.5*asp-0.12,-0.28)+0.035*vec2(sin(t*0.42),cos(t*0.33));
vec2 q=p-c;
float m=1.0-smoothstep(0.08,0.62,length(q*vec2(0.85,1.0)));
vec3 col=u_c0;
col*=0.975+0.03*n(fc*0.08);
col=mix(col,col*1.12+u_c3*0.08,m*m);
float w=(n(p*5.0+vec2(t*0.04,0.0))-0.5)*0.5;
float F=170.0;
float a1=0.62;
float a2=a1+0.03+0.006*sin(t*0.5236);
float f1=dot(p,vec2(cos(a1),sin(a1)))*F+w;
float f2=dot(p,vec2(cos(a2),sin(a2)))*F+t*0.08+w*0.6;
float mo=0.5+0.5*cos(6.2832*(f1-f2));
float aa=0.75*F/R.y;
float lw=mix(0.06,0.3,mo);
float ln=1.0-smoothstep(lw-aa,lw+aa,abs(fract(f1)-0.5));
vec3 tint=mix(u_c3,u_c1,0.3);
col=mix(col,tint,ln*m*0.42);
float rim=smoothstep(0.0,0.35,m)*(1.0-smoothstep(0.35,0.7,m));
vec2 g=fract(fc/7.0)-0.5;
float hr=0.4*sqrt(rim)*(0.4+0.6*mo);
float dt=1.0-smoothstep(hr-0.11,hr+0.11,length(g));
col=mix(col,tint,dt*rim*0.35);
float hb=max(3.0,R.y*0.004);
float band=1.0-smoothstep(hb-0.75,hb+0.75,fc.y);
float P=22.0;
float s=fract((fc.x+fc.y-t*7.0)/P);
float ea=1.5/P;
float red=smoothstep(0.0,ea,s)*(1.0-smoothstep(0.32,0.32+ea,s));
float blu=smoothstep(0.5,0.5+ea,s)*(1.0-smoothstep(0.82,0.82+ea,s));
float run=smoothstep(0.25,0.85,fc.x/R.x);
col=mix(col,u_c2,red*band*run*0.9);
col=mix(col,mix(u_c3,u_c1,0.2),blu*band*run*0.9);
col+=(h(fc)-0.5)*0.03;
gl_FragColor=vec4(col,1.0);
}",
  "colors": [
    "#1f2a3a",
    "#f6f1e7",
    "#c8432f",
    "#2f4f8f"
  ],
  "reduced": {
    "kind": "fade",
    "at": 4.0,
    "ms": 400,
    "note": "A still navy ground with a fine blue line screen and its moire bands in one corner, and a thin red and blue striped hairline on the bottom edge."
  },
  "cardIds": [
    "envelopes"
  ],
  "lensIds": [],
  "styles": [
    "illustrative-handmade",
    "retro-pixel-halftone"
  ]
}
